<!-- eslint-disable no-unreachable -->
<!-- eslint-disable no-unused-vars -->
<template>
  <div>
    <el-upload
      :action="uploadAction"
      :data="formData"
      :headers="{ 'X-Auth-Token': token, 'X-Requested-With': 'XMLHttpRequest' }"
      :show-file-list="showFileList"
      :list-type="listType"
      :on-preview="handlePictureCardPreview"
      :on-remove="handleRemove"
      :on-success="handleSuccess"
      :on-error="handleError"
      :on-progress="handleProgress"
      :on-change="handleChange"
      :before-upload="handleBeforeUpload"
      :before-remove="handleBeforeRemove"
      :limit="limit"
      :file-list="optFileList"
      :name="inputFileName"
      :class="uploadClass"
      :auto-upload="autoUpload"
      :accept="accept"
      ref="vrUpload"
      :key="key"
    >
      <el-progress
        class="single-file-progress"
        v-if="!showFileList && showSingleFileProgress"
        :text-inside="true"
        :stroke-width="24"
        :percentage="singleFilePercentage"
        status="success"
      ></el-progress>
      <!-- 自定义触发后,组件本身自带的-->
      <slot name="trigger">
        <img
          v-if="!showFileList && imageUrl"
          :src="imageUrl"
          class="show-img"
        />
        <i class="el-icon-plus cover-uploader-icon" v-else></i>
        <span
          v-if="!showFileList && imageUrl && showDelAction"
          class="el-upload-list__item-actions"
        >
          <span class="el-upload-list__item-delete" @click.stop="clear()">
            <i class="el-icon-delete"></i>
          </span>
        </span>
        <div class="el-upload__tip" slot="tip" v-if="tip">{{ tip }}</div>
      </slot>
      <div
        slot="file"
        slot-scope="{ file }"
        class="el-upload-list__item__li_div"
        :data-sort="file.sort || 0"
        :data-sid="file.id"
        v-if="mode === 'scene'"
        @click="onSceneChange(file, $event)"
      >
        <el-tooltip
          class="item"
          effect="dark"
          :content="file.name"
          placement="top"
        >
          <div
            class="el-upload-list__item__li_div_body"
            :class="activeFileId === file.id ? 'active' : ''"
          >
            <img class="el-upload-list__item-thumbnail" :src="file.url" alt />
            <label class="el-upload-list__item-status-label">
              <i class="el-icon-upload-success el-icon-check"></i>
            </label>
            <span class="el-upload-list__item-actions">
              <!-- <span class="el-upload-list__item-preview" @click="handlePictureCardPreview(file)">
                <i class="el-icon-zoom-in"></i>
              </span>-->
              <span
                class="el-upload-list__item-edit"
                @click="actionUpdate(file)"
              >
                <i class="el-icon-edit"></i>
              </span>
              <!-- ['view', 'hotpot'].includes(currentToolbarCode) &&  -->
              <span
                class="el-upload-list__item-delete"
                @click="actionRemove(file)"
                v-if="activeFileId !== file.id"
              >
                <i class="el-icon-delete"></i>
              </span>
            </span>
          </div>
        </el-tooltip>
      </div>
    </el-upload>
    <el-dialog :visible.sync="dialogVisible">
      <img width="100%" :src="dialogImageUrl" alt />
    </el-dialog>
    <el-dialog
      title="图片裁剪"
      v-if="cropImg"
      :visible.sync="cropDialogVisible"
      :width="cropDialogWidth"
      :top="cropDialogTop"
      :modal="cropDialogModal"
      :modal-append-to-body='cropDialogModalAppendToBody'
      :append-to-body='cropDialogAppendToBody'
      :destroy-on-close="cropDialogDestroyOnClose"
    >
      <div class="cropper-content" :class="cropperClass">
        <div class="cropper-box">
          <div class="cropper">
            <vueCropper
              ref="cropper"
              :img="cropper.img"
              :outputSize="cropper.outputSize"
              :outputType="cropper.outputType"
              :info="cropper.info"
              :canScale="cropper.canScale"
              :autoCrop="cropper.autoCrop"
              :autoCropWidth="cropper.autoCropWidth"
              :autoCropHeight="cropper.autoCropHeight"
              :fixed="cropper.fixed"
              :fixedNumber="cropper.fixedNumber"
              :full="cropper.full"
              :fixedBox="cropper.fixedBox"
              :canMove="cropper.canMove"
              :canMoveBox="cropper.canMoveBox"
              :original="cropper.original"
              :centerBox="cropper.centerBox"
              :height="cropper.height"
              :infoTrue="cropper.infoTrue"
              :maxImgSize="cropper.maxImgSize"
              :enlarge="cropper.enlarge"
              :mode="cropper.mode"
              @realTime="realTime"
              @imgLoad="imgLoad"
            ></vueCropper>
          </div>
        </div>
        <div class="show-preview">
          <div :style="previews.div" class="preview">
            <img :src="previews.url" :style="previews.img" />
          </div>
        </div>
      </div>
      <div slot="footer" class="dialog-footer">
        <el-button @click="cropDialogVisible = false">取 消</el-button>
        <el-button
          type="primary"
          @click="finishCropper"
          :loading="cropperLoading"
          >确认</el-button
        >
      </div>
    </el-dialog>
  </div>
</template>
<script>
// eslint-disable-next-line no-unused-vars
import Sortable from 'sortablejs'
import {
  commonUploadUrlAction,
  sceneUploadUrlAction,
  upload,
} from '@/api/upload'
import { mapGetters } from 'vuex'
import { VueCropper } from 'vue-cropper'
import { openLoginDialog } from '@/components/dialog/openLoginHandler'
export default {
  // name: 'VrUpload',
  computed: {
    ...mapGetters(['token']),
    uploadAction() {
      if (this.action) {
        return this.action
      }
      return this.mode === 'scene'
        ? sceneUploadUrlAction()
        : commonUploadUrlAction()
    },
    inputFileName() {
      return this.mode === 'scene' ? 'scene' : 'file'
    },
  },
  props: {
    accept: {
      type: String,
      default: 'image/*',
    },
    autoUpload: {
      type: Boolean,
      default: true,
    },
    cropImg: {
      type: Boolean,
      default: false,
    },
    cropDialogModal: {
      type: Boolean,
      default: true,
    },
    cropFixed: {
      type: Boolean,
      default: true,
    },
    autoCropWidth: {
      type: Number,
      default: 512,
    },
    autoCropHeight: {
      type: Number,
      default: 512,
    },
    cropDialogTop: {
      type: String,
      default: '15vh',
    },
    listType: {
      type: String,
      default: 'picture-card',
    },
    uploadClass: {
      type: String,
      default: 'upload-scene',
    },
    maxFileSize: {
      type: Number,
      default: 2 * 1024 * 1024,
    },
    showFileList: {
      type: Boolean,
      default: false,
    },
    tip: {
      type: String,
      default: '',
    },
    removeTip: {
      type: String,
      default: '删除后场景下所有设置也都将会被删除, 是否继续?',
    },
    mode: {
      type: String,
      default: 'avatar',
    },
    limit: undefined,
    fileList: {
      type: Array,
      default() {
        return []
      },
    },
    maxFileCount: {
      type: Number,
      default: 0,
    },
    action: {
      type: String,
      default: '',
    },
    currentToolbarCode: String,
    enableSort: {
      type: Boolean,
      default: false,
    },
    formData: {
      type: Object,
      default() {
        return {}
      },
    },
    showDelAction: {
      type: Boolean,
      default: false,
    },
    cropperClass: {
      type: String,
      default: ''
    },
    cropDialogWidth: {
      type: String,
      default: '1200px'
    },
    cropDialogModalAppendToBody: {
      type: Boolean,
      default: true
    },
    cropDialogAppendToBody: {
      type: Boolean,
      default: false
    },
    cropDialogDestroyOnClose: {
      type: Boolean,
      default: false
    }
  },
  data() {
    return {
      imageUrl: '',
      dialogImageUrl: '',
      optFileList: [],
      dialogVisible: false,
      showSingleFileProgress: false,
      singleFilePercentage: 0,
      cropDialogVisible: false,
      previews: {},
      cropper: {
        img: '',
        outputSize: 1, //裁剪生成图片的质量(可选0.1 - 1)
        outputType: 'jpeg', //裁剪生成图片的格式（jpeg || png || webp）
        info: true, //图片大小信息
        canScale: true, //图片是否允许滚轮缩放
        autoCrop: true, //是否默认生成截图框
        autoCropWidth: 512, //默认生成截图框宽度
        autoCropHeight: 512, //默认生成截图框高度
        fixed: true, //是否开启截图框宽高固定比例
        fixedNumber: [1, 1], //截图框的宽高比例
        full: false, //false按原比例裁切图片，不失真
        fixedBox: true, //固定截图框大小，不允许改变
        canMove: false, //上传图片是否可以移动
        canMoveBox: true, //截图框能否拖动
        original: false, //上传图片按照原始比例渲染
        centerBox: false, //截图框是否被限制在图片里面
        height: true, //是否按照设备的dpr 输出等比例图片
        infoTrue: false, //true为展示真实输出图片宽高，false展示看到的截图框宽高
        maxImgSize: 3000, //限制图片最大宽度和高度
        enlarge: 1, //图片根据截图框输出比例倍数
        mode: 'cover', //图片默认渲染方式
      },
      cropperLoading: false,
      activeFileId: null,
      key: 1,
      fileCount: 0,
      uploading: false,
      sortable: null,
    }
  },
  watch: {
    fileCount(newVal) {
      if (this.maxFileCount > 0 && newVal >= this.maxFileCount) {
        this.$refs.vrUpload.$el.querySelector('.el-upload').style.display =
          'none'
      }
      if (
        this.maxFileCount > 0 &&
        newVal < this.maxFileCount &&
        this.$refs.vrUpload.$el.querySelector('.el-upload').style.display ===
          'none'
      ) {
        this.$refs.vrUpload.$el.querySelector('.el-upload').style.display =
          'inline-block'
      }
    },
  },
  components: {
    VueCropper,
  },
  created() {
    this.cropper.autoCropWidth = this.autoCropWidth
    this.cropper.autoCropHeight = this.autoCropHeight
    this.cropper.fixed = this.cropFixed
    if (!this.showFileList && this.fileList.length) {
      this.imageUrl = this.fileList[0]['url']
    }
    this.optFileList = this.fileList
    this.fileCount = this.optFileList.length
    this.$bus.$on('onSceneChanged', this.handleChangeScene)
  },
  beforeDestroy() {
    if (this.sortable) {
      this.sortable.destroy()
    }
    this.$bus.$off('onSceneChanged', this.handleChangeScene)
  },
  methods: {
    initFileList(fileList) {
      this.optFileList = fileList
      if (this.optFileList.length) {
        this.fileCount = this.optFileList.length
        this.activeFileId = this.optFileList[0]['id']
        this.imageUrl = fileList[0]['url']
      }

      if (this.enableSort) {
        this.$nextTick(() => {
          this.initSortable()
        })
      }
    },
    clear() {
      this.optFileList = []
      this.imageUrl = ''
      this.$refs.vrUpload.clearFiles()
      this.$emit('onClearFile')
    },
    onSceneChange(file, event) {
      if ('I' === event.target.nodeName || this.uploading) {
        return false
      }

      this.activeFileId = file.id
      if (file.id) {
        this.$nextTick(() => {
          this.$bus.$emit('onCurrentSceneChange', file)
        })
      }
    },
    actionRemove(file) {
      this.$confirm(this.removeTip, '提示', {
        confirmButtonText: '确定',
        cancelButtonText: '取消',
        type: 'warning',
      })
        .then(() => {
          console.log('before remove vr scene file:')
          // console.log('before remove vr scene file:', file, this.optFileList)
          const newFileList = this.optFileList.filter((item) => {
            return item.id !== file.id
          })
          this.$nextTick(() => {
            this.optFileList = newFileList
            this.$emit('onRemove', file, this.optFileList)
          })
        })
        .catch(() => {})
    },
    actionUpdate(file) {
      this.$emit('onUpdate', file)
    },
    handleRemove(file, fileList) {
      if (!this.showFileList) {
        this.percentage = 0
        this.showSingleFileProgress = false
      }
      console.log('handleRemove file:')
      // console.log('handleRemove file:', file, fileList)
      this.$emit('onRemove', file, fileList)
      this.fileCount = fileList.length
    },
    handlePictureCardPreview(file) {
      console.log('handlePictureCardPreview file:')
      // console.log('handlePictureCardPreview file:', file)
      this.dialogImageUrl = file.url
      this.dialogVisible = true
    },
    // eslint-disable-next-line no-unused-vars
    handleSuccess(response, file, fileList) {
      this.fileCount = fileList.length
      console.log('handleSuccess file:')
      // console.log('handleSuccess file:', response, file, fileList)
      this.uploading = false
      if (response.code !== 0) {
        this.$message.error(response.message)
        this.showSingleFileProgress = false
        this.singleFilePercentage = 0
        return false
      }
      // 此项作为单上传和多上传的标识
      if (!this.showFileList) {
        setTimeout(() => {
          this.showSingleFileProgress = false
        }, 1500)
        this.imageUrl = URL.createObjectURL(file.raw)
      }
      this.$emit('onSuccess', response.data)
    },
    // eslint-disable-next-line no-unused-vars
    handleError(err, file, fileList) {
      const response =
        typeof err.message !== 'object' ? JSON.parse(err.message) : err.message
      if (response.code !== 0) {
        this.$message.error(response.message || '上传失败了, 请联系平台')
      }
      
      if (err.status === 401) {
        this.$store.dispatch('user/resetToken').then(() => {
          openLoginDialog(this.$store.getters.systemTitle, 'login')
        })
      }
      this.uploading = false
      if (!this.showFileList) {
        this.showSingleFileProgress = false
      }
    },
    // eslint-disable-next-line no-unused-vars
    handleProgress(event, file, fileList) {
      console.log('handleProgress file:')
      // console.log('handleProgress file:', event, file, fileList)
      this.uploading = true
      if (!this.showFileList) {
        this.singleFilePercentage = event.percent
      }
    },
    // eslint-disable-next-line no-unused-vars
    handleChange(file, fileList) {
      // console.log('handleChange file:', file, fileList)
      if (!this.showFileList && !this.autoUpload && this.cropImg) {
        if (file.raw.type.indexOf('image') < 0) {
          this.$message.error('只能上传图片!')
          return false
        }
        if (file.raw.size > this.maxFileSize) {
          const sizeFormat = this.maxFileSize / 1024 / 1024
          this.$message.error(`大小不能超过 ${sizeFormat}MB!`)
          return false
        }
        this.$nextTick(() => {
          this.cropper.img = URL.createObjectURL(file.raw)
          this.cropDialogVisible = true
        })
      }
    },
    // eslint-disable-next-line no-unused-vars
    handleBeforeUpload(file) {
      console.log('handleBeforeUpload file:', file)
      if (
        this.accept.indexOf('image/') >= 0 &&
        file.type.indexOf('image') < 0
      ) {
        this.$message.error('只能上传图片!')
        return false
      }

      if (
        this.accept.indexOf('video/') >= 0 &&
        file.type.indexOf('video') < 0
      ) {
        this.$message.error('只能上传视频!')
        return false
      }

      if (file.size > this.maxFileSize) {
        const sizeFormat = this.maxFileSize / 1024 / 1024
        this.$message.error(`大小不能超过 ${sizeFormat}MB!`)
        return false
      }
      if (this.maxFileCount > 0 && this.fileCount >= this.maxFileCount) {
        this.$message.error(`最多上传${this.maxFileCount}图片!`)
        return false
      }
      if (!this.showFileList && this.autoUpload) {
        this.showSingleFileProgress = true
        this.singleFilePercentage = 0
      }
    },
    // eslint-disable-next-line no-unused-vars
    handleBeforeRemove(file, fileList) {
      console.log('handleBeforeRemove file:', file, fileList)
    },
    realTime(data) {
      this.previews = data
    },
    imgLoad(msg) {
      console.log('工具初始化函数=====' + msg)
    },
    blobToFile(Blob, fileName) {
      //兼容IE
      Blob.lastModifiedDate = new Date()
      Blob.name = fileName
      return new File([Blob], fileName)
    },
    finishCropper() {
      this.$refs.cropper.getCropBlob((data) => {
        let form = new FormData()
        let file = this.blobToFile(data, 'file.jpg')
        form.append('file', file)
        upload(form).then((response) => {
          this.imageUrl = URL.createObjectURL(data)
          this.cropperLoading = false
          this.cropDialogVisible = false
          this.$emit('onSuccess', response)
        })
      })
    },
    initSortable() {
      if (
        !this.$refs.vrUpload.$children ||
        !this.$refs.vrUpload.$children.length ||
        !this.$refs.vrUpload.$children[0].$el
      ) {
        return
      }
      const $el = this.$refs.vrUpload.$children[0].$el
      const oldFiles = this.optFileList
      // eslint-disable-next-line no-unreachable
      this.sortable = Sortable.create($el, {
        dataIdAttr: 'data-sort',
        animation: 1000,
        draggable: '.el-upload-list__item',
        // eslint-disable-next-line no-unused-vars
        onStart: (evt) => {
          // 拖拽
          // var itemEl = evt.item
          console.log('拖拽onStart')
        },
        // eslint-disable-next-line no-unused-vars
        onEnd: (evt) => {
          // 拖拽
          // var itemEl = evt.item
          console.log('拖拽onEnd')
        },
        // eslint-disable-next-line no-unused-vars
        onAdd: (evt) => {
          // var itemEl = evt.item
          console.log('拖拽onAdd')
        },
        // eslint-disable-next-line no-unused-vars
        onRemove: (evt) => {
          console.log('拖拽onRemove')
        },
        onUpdate: (evt) => {
          console.log('拖拽onUpdate')
          const newIndex = evt.newIndex
          const oldIndex = evt.oldIndex
          const dataset =
            'LI' === evt.item.nodeName
              ? evt.item.firstChild.dataset
              : evt.item.dataset
          if (!dataset) {
            return
          }

          const to = { sid: dataset.sid, sortNum: newIndex }
          const beforeFile = oldFiles.find(
            (m) => parseInt(m.sort) === newIndex
          )
          if (beforeFile) {
            const from = { sid: beforeFile.id, sortNum: oldIndex }
            this.$bus.$emit('onSceneSortableEnd', to, from)
          }
        },
        // onUpdate: (evt) => {
        //   // console.log('onUpdate:', evt)
        // },
      })
      // console.log('this.sortable:', this.sortable)
    },
    handleChangeScene(sceneId) {
      this.activeFileId = sceneId
    },
  },
}
</script>
