import request from '@/utils/request'

export function commonUploadUrlAction() {
  return process.env.VUE_APP_API + '/upload/file'
}

export function sceneUploadUrlAction() {
  return process.env.VUE_APP_API + '/product/scene/upload'
}

export function upload(data) {
  return request({
    url: '/upload/file',
    method: 'post',
    headers: { 'Content-Type': 'multipart/form-data;boundary = ' + new Date().getTime() },
    data,
  })
}

export function removeFiles(data) {
  return request({
    url: '/upload/remove',
    method: 'post',
    data,
  })
}